selector_to_html = {"a[href=\"features.html#device-runtime-and-management-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Device runtime and management API<a class=\"headerlink\" href=\"#device-runtime-and-management-api\" title=\"Link to this heading\">#</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.flagos</span></code> module exposes a complete device interface:</p>", "a[href=\"#design-principles\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Design principles<a class=\"headerlink\" href=\"#design-principles\" title=\"Link to this heading\">#</a></h2><p>Torch-FL is built on five principles:</p>", "a[href=\"architecture.html#import-time-phases\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Import-time phases<a class=\"headerlink\" href=\"#import-time-phases\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">torch_fl</span></code> runs a fixed sequence of side effects. The order is load-bearing \u2014 a wrong order produces a <code class=\"docutils literal notranslate\"><span class=\"pre\">dlopen</span></code> abort or a wrong-vendor build rather than a Python exception \u2014 so it lives in one place:</p>", "a[href=\"architecture.html#operator-dispatch\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Operator dispatch<a class=\"headerlink\" href=\"#operator-dispatch\" title=\"Link to this heading\">#</a></h2><p>Operator implementations are reached through one dispatch key and one routing table:</p>", "a[href=\"architecture.html#device-registration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Device registration<a class=\"headerlink\" href=\"#device-registration\" title=\"Link to this heading\">#</a></h2><p>At import, Torch-FL claims the <code class=\"docutils literal notranslate\"><span class=\"pre\">PrivateUse1</span></code> dispatch key and publishes it under the name <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>:</p>", "a[href=\"features.html#framework-and-ecosystem-compatibility\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Framework and ecosystem compatibility<a class=\"headerlink\" href=\"#framework-and-ecosystem-compatibility\" title=\"Link to this heading\">#</a></h2><p>Import-time shims adapt other projects\u2019 assumptions about the device, all of them optional and measurable through their own switch:</p>", "a[href=\"features.html#observability\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Observability<a class=\"headerlink\" href=\"#observability\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#status-levels\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Status levels<a class=\"headerlink\" href=\"#status-levels\" title=\"Link to this heading\">#</a></h2><p>A capability existing in the Torch-FL codebase does not imply that every platform implements or validates it. See the <a class=\"reference internal\" href=\"../reference/compatibility.html\"><span class=\"doc\">compatibility matrix</span></a> for per-platform detail.</p>", "a[href=\"features.html#execution-paths\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Execution paths<a class=\"headerlink\" href=\"#execution-paths\" title=\"Link to this heading\">#</a></h2><p>Torch-FL implements four operator execution strategies, and a platform may combine several of them. These are implementation strategies, not user-selectable product tiers.</p>", "a[href=\"features.html#hardware-support\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware support<a class=\"headerlink\" href=\"#hardware-support\" title=\"Link to this heading\">#</a></h2><p>Per-capability detail \u2014 including <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code>, distributed and profiler status per platform \u2014 is in the <a class=\"reference internal\" href=\"../reference/compatibility.html\"><span class=\"doc\">compatibility matrix</span></a>.</p>", "a[href=\"#quick-start\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><p>Operator routing (FlagGems compiler kernels, vendor-native kernels, compatibility boxing, or CPU fallback) is determined by platform detection and runtime configuration. The code above works unchanged across all supported accelerators.</p>", "a[href=\"features.html#training-stack\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Training stack<a class=\"headerlink\" href=\"#training-stack\" title=\"Link to this heading\">#</a></h2>", "a[href=\"architecture.html#component-layout\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Component layout<a class=\"headerlink\" href=\"#component-layout\" title=\"Link to this heading\">#</a></h2>", "a[href=\"architecture.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Architecture<a class=\"headerlink\" href=\"#architecture\" title=\"Link to this heading\">#</a></h1><p>Torch-FL registers one PyTorch device and routes every operator that reaches it.</p><p><a data-lightbox=\"image-set\" href=\"../_images/torch-fl.png\">\n<img alt=\"Torch-FL architecture\" src=\"../_images/torch-fl.png\"/></a>\n</p>", "a[href=\"../reference/compatibility.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Compatibility and Platform Support<a class=\"headerlink\" href=\"#compatibility-and-platform-support\" title=\"Link to this heading\">#</a></h1><h2>Status definitions<a class=\"headerlink\" href=\"#status-definitions\" title=\"Link to this heading\">#</a></h2>", "a[href=\"features.html#low-precision-and-quantization\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Low-precision and quantization<a class=\"headerlink\" href=\"#low-precision-and-quantization\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl.quantization</span></code> provides low-precision conversion helpers and modules:</p>", "a[href=\"#torch-fl-overview\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Torch-FL Overview<a class=\"headerlink\" href=\"#torch-fl-overview\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl</span></code> is a custom PyTorch device plugin built on the <code class=\"docutils literal notranslate\"><span class=\"pre\">PrivateUse1</span></code> extension mechanism. It registers <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\">FlagGems</a> high-performance Triton operators, vendor-native operator libraries, and CUDA compatibility kernels behind one device name: <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>.</p><p>Accelerator vendors ship different runtimes, compiler stacks, and PyTorch integration strategies. Torch-FL hides those differences behind a unified runtime and operator-routing layer, so users program against standard PyTorch APIs and a single device name, and the plugin selects a kernel implementation per operator based on platform capability and configuration.</p>", "a[href=\"features.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Features<a class=\"headerlink\" href=\"#features\" title=\"Link to this heading\">#</a></h1><h2>One device, standard PyTorch APIs<a class=\"headerlink\" href=\"#one-device-standard-pytorch-apis\" title=\"Link to this heading\">#</a></h2><p>Every supported accelerator is programmed through the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device. Model code, optimizers, and third-party libraries keep using standard PyTorch APIs; moving between accelerators does not require changing tensor device strings, kernel launches, or the model.</p><p>The device module is installed at import time with <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.utils.rename_privateuse1_backend(\"flagos\")</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._register_device_module()</span></code>, so <code class=\"docutils literal notranslate\"><span class=\"pre\">device=\"flagos\"</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.flagos.*</span></code> methods, tensor methods, and storage work the same way as a first-class PyTorch device.</p>", "a[href=\"features.html#one-device-standard-pytorch-apis\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">One device, standard PyTorch APIs<a class=\"headerlink\" href=\"#one-device-standard-pytorch-apis\" title=\"Link to this heading\">#</a></h2><p>Every supported accelerator is programmed through the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device. Model code, optimizers, and third-party libraries keep using standard PyTorch APIs; moving between accelerators does not require changing tensor device strings, kernel launches, or the model.</p><p>The device module is installed at import time with <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.utils.rename_privateuse1_backend(\"flagos\")</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._register_device_module()</span></code>, so <code class=\"docutils literal notranslate\"><span class=\"pre\">device=\"flagos\"</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.flagos.*</span></code> methods, tensor methods, and storage work the same way as a first-class PyTorch device.</p>", "a[href=\"features.html#per-operator-backend-routing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Per-operator backend routing<a class=\"headerlink\" href=\"#per-operator-backend-routing\" title=\"Link to this heading\">#</a></h2><p>Each built wheel ships one routing table, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl/configs/backends_&lt;platform&gt;.conf</span></code>, holding <code class=\"docutils literal notranslate\"><span class=\"pre\">op</span> <span class=\"pre\">=</span> <span class=\"pre\">backend</span></code> entries for the platform it was built for. Routing is decided per operator \u2014 not per device or per model \u2014 and can mix backends inside one model:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
